<section class="section"><h1>Review complete cost reconciliation</h1>
<?php if ($cost === null): ?><p>Invoice family needs review.</p><?php else: ?>
<p>Invoice root <?= (int) $cost['root_id'] ?>: USD <?= esc($cost['amount']) ?>, <?= esc($cost['occurred_on']) ?>, <?= esc($cost['vendor']) ?>, reference <?= esc((string) $cost['reference']) ?>.</p>
<p>Expense <?= (int) $expense['id'] ?>: USD <?= esc($expense['amount']) ?>, <?= esc($expense['expense_date']) ?>, <?= esc((string) $expense['vendor']) ?>, reference <?= esc((string) $expense['payment_reference']) ?>.</p>
<p>Expense evidence records: <?= count($expense['evidence']) ?>. Invoice family facts: <?= count($cost['entries']) ?>. Financial reports keep the expense date and amount.</p>
