<?php foreach (['cost_root_entry_id' => $cost['root_id'], 'operating_expense_id' => $expense['id'], 'expected_damage_state' => $family['fingerprint'], 'expected_expense_state' => $expenseSource['fingerprint'], 'amount' => $cost['amount'], 'currency' => 'USD'] as $name => $value): ?><input type="hidden" name="<?= esc($name, 'attr') ?>" value="<?= esc((string) $value, 'attr') ?>"><?php endforeach; ?>
<?php if ($predecessor !== null): ?><input type="hidden" name="reconciliation_id" value="<?= (int) $predecessor['id'] ?>"><input type="hidden" name="expected_reconciliation_state" value="<?= esc($predecessor['state'], 'attr') ?>"><?php endif; ?>
<label>Authority / reconciliation reason<textarea name="reason" required maxlength="2000"></textarea></label>
<?php if ($cost['occurred_on'] !== $expense['expense_date']): ?><label>Explain differing invoice and report dates<textarea name="date_difference_reason" required maxlength="2000"></textarea></label><?php endif; ?>
<?php if ((string) $cost['vendor'] !== (string) $expense['vendor'] || (string) $cost['reference'] !== (string) $expense['payment_reference']): ?><label>Explain vendor / reference differences<textarea name="descriptor_review_reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="descriptor_review_confirmed" value="1" required> I reviewed the differing descriptors and evidence.</label><?php endif; ?>
<?php foreach (['whole_fact_confirmed' => 'These sources represent the same complete real-world cost.', 'no_other_job_confirmed' => 'No portion belongs to another repair or job.', 'no_other_expense_confirmed' => 'No additional expense source represents this same whole fact.', 'not_partial_confirmed' => 'This is not a partial allocation or mixed-purpose expense.', 'confirmed' => 'Record this decision and retain both source histories.'] as $name => $label): ?><label><input type="checkbox" name="<?= esc($name, 'attr') ?>" value="1" required> <?= esc($label) ?></label><?php endforeach; ?>
<button type="submit"><?= $predecessor === null ? 'Reconcile complete cost' : 'Replace reconciliation' ?></button></form><?php endif; endif; ?>
